7	)
8	
9	// These tests pin credential redaction for a schemeless upstream — an
10	// address written with a leading "//" and no scheme, e.g.
11	// "//alice:pw%4@api.internal/v1". Such an upstream is always rejected
12	// (never promoted to http or https), but its failure diagnostic must hide
13	// the whole username and optional password exactly like a scheme-bearing
14	// address: the address may only appear as "//***@host/...", the '@', host,
15	// port and base path are kept, and neither the original nor the decoded
16	// credential bytes may appear anywhere in the reason. A malformed escape in
17	// the userinfo is reported as a userinfo problem without quoting the bad
18	// fragment; a bad host or base path keeps its own diagnostic and its
19	// fragment, and the existing error-selection order is unchanged.
20	
21	// schemelessRedactionCase is one upstream and the exact redacted address
22	// the reason must quote, alongside bytes that must never appear.
23	type schemelessRedactionCase struct {
24		name     string
25		upstream string
26		shown    string
27		hidden   []string
28	}
29	
30	func schemelessConfig(upstream string) string {
31		return `{"routes":[{"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"` + upstream + `"}]}`
32	}
33	
34	// assertSchemelessRejected parses the one-route config, requires
35	// invalid_config with no config handed back, a route/id/upstream-located
36	// reason that never calls the legal JSON broken, and (when shown is set)
37	// the redacted address quoted in the reason with none of the hidden bytes.
38	func assertSchemelessRejected(t *testing.T, src, shown string, hidden []string) *Failure {
39		t.Helper()
40		cfg, f := ParseConfig([]byte(src))
41		if f == nil || f.Code != "invalid_config" {
42			t.Fatalf("got cfg=%+v f=%+v, want invalid_config", cfg, f)
43		}
44		if cfg != nil {
45			t.Fatalf("a rejected config must not be returned, got %+v", cfg)
46		}
47		for _, want := range []string{"route 1", `"api"`, "upstream"} {
48			if !strings.Contains(f.Reason, want) {
49				t.Fatalf("reason = %q, want substring %q", f.Reason, want)
50			}
51		}
52		if strings.Contains(f.Reason, "not valid JSON") {
53			t.Fatalf("a schemeless upstream is a content error, not a JSON syntax failure: %q", f.Reason)
54		}
55		if shown != "" {
56			if !strings.Contains(f.Reason, `"`+shown+`"`) {
57				t.Fatalf("reason = %q, want the redacted address %q quoted", f.Reason, shown)
58			}
59		}
60		for _, leaked := range hidden {
61			if strings.Contains(f.Reason, leaked) {
62				t.Fatalf("reason = %q leaks credential %q", f.Reason, leaked)
63			}
64		}
65		return f
66	}
