68	// TestSchemelessUpstreamHeadlineRedaction drives the headline case:
69	// //alice:pw%4@api.internal/v1 fails the userinfo-escape content rule and
70	// must be shown only as //***@api.internal/v1.
71	func TestSchemelessUpstreamHeadlineRedaction(t *testing.T) {
