386			t.Fatalf("legal credentials must survive the save: %s", savedLegal)
387		}
388		reparsed := mustConfig(t, string(savedLegal))
389		res := resolveJSON(t, reparsed, `{"method":"GET","target":"/x"}`)
390		if want := "https://alice:s3cr%40t@host.internal/v1/x"; res.UpstreamURL != want {
391			t.Fatalf("reparsed upstreamURL = %q, want %q", res.UpstreamURL, want)
392		}
