8	// These tests pin at the command boundary the credential-redaction fix for
9	// a schemeless upstream — an address written with a leading "//" and no
10	// scheme, e.g. //alice:pw%4@api.internal/v1. Such an upstream is always
11	// rejected (resolve never adds http or https on the user's behalf), but the
12	// failure contract is the same as for a scheme-bearing address: non-zero
13	// exit, completely empty stdout and one JSON error on stderr with code
14	// invalid_config, the reason locates the offending route by its 1-based
15	// position, id and the upstream field, the address may only appear as
16	// "//***@host/..." and neither the original nor the decoded credential may
17	// appear anywhere. A bad escape in the base path keeps the path-escape
18	// diagnostic while only the credentials are hidden.
19	
20	// TestResolveCLISchemelessBadUserinfoEscapeRejectsConfig drives the
21	// headline case on the second route, which the request never hits: the
22	// whole config is rejected up front and the credential never reaches
23	// stdout, stderr in raw form, or any decoded form.
24	func TestResolveCLISchemelessBadUserinfoEscapeRejectsConfig(t *testing.T) {
25		config := `{
26		  "routes": [
27		    {"id": "api", "methods": ["GET"], "pathPrefix": "/api", "upstream": "http://api.internal/v1"},
28		    {"id": "admin", "methods": ["GET"], "pathPrefix": "/admin", "upstream": "//alice:pw%4@api.internal/v1"}
29		  ]
30		}`
31		res := runResolveCLI(t, config, `{"method":"GET","target":"/api/items"}`)
32	
33		if res.exitCode == 0 {
34			t.Fatalf("exit code = 0, want non-zero")
35		}
36		if len(res.stdout) != 0 {
37			t.Fatalf("stdout = %q, want completely empty on failure (no half result)", res.stdout)
38		}
39		var fail struct {
40			Code   string `json:"code"`
41			Reason string `json:"reason"`
42		}
43		decodeOneJSON(t, res.stderr, "stderr", &fail)
44		if fail.Code != "invalid_config" {
45			t.Fatalf("code = %q, want invalid_config", fail.Code)
46		}
47		for _, want := range []string{
48			"route 2",
49			`"admin"`,
50			"upstream",
51			"invalid percent escape in its userinfo",
52			`"//***@api.internal/v1"`,
53		} {
54			if !strings.Contains(fail.Reason, want) {
55				t.Fatalf("reason = %q, want substring %q", fail.Reason, want)
56			}
57		}
58		for _, leaked := range []string{"alice", "pw%4", "p@", `"%4"`, "//alice", "https://", "http://"} {
59			if strings.Contains(fail.Reason, leaked) {
60				t.Fatalf("reason = %q leaks %q", fail.Reason, leaked)
61			}
62		}
63		if strings.Contains(fail.Reason, "not valid JSON") {
64			t.Fatalf("a schemeless upstream is a content error, not a JSON syntax failure: %q", fail.Reason)
65		}
66	}
