68	// TestResolveCLISchemelessBadUserinfoEscapeVariants covers the malformed
69	// credential shapes on a first route, proving the command output is
70	// credential-free for each while the redacted address keeps "//".
71	func TestResolveCLISchemelessBadUserinfoEscapeVariants(t *testing.T) {
72		cases := []struct {
73			name     string
74			upstream string
75			shown    string
76			hidden   []string
77		}{
78			{"truncated password escape", "//alice:pw%2@host.internal/base", "//***@host.internal/base", []string{"alice", "pw%2", `"%2"`}},
79			{"lone percent password", "//alice:pw%@host/base", "//***@host/base", []string{"alice", "pw%", `"%"`}},
80			{"bad username with password", "//%zz:secret@host.internal/base", "//***@host.internal/base", []string{"secret", "%zz", `"%zz"`}},
81			{"username only", "//al%zz@host/base", "//***@host/base", []string{"al%zz", `"%zz"`}},
82		}
83		for _, tc := range cases {
84			t.Run(tc.name, func(t *testing.T) {
85				config := `{"routes":[{"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"` + tc.upstream + `"}]}`
